(()=>{'use strict';const photos=[...document.querySelectorAll('.album-photo')],dialog=document.getElementById('album-lightbox');let current=0;function show(i){current=(i+photos.length)%photos.length;const p=photos[current];dialog.classList.toggle('cropped-photo',p.dataset.screenshot==='true');dialog.querySelector('img').src=p.dataset.image;dialog.querySelector('img').alt=p.dataset.caption;dialog.querySelector('.album-full-caption').textContent=p.dataset.caption;dialog.querySelector('.lightbox-nav span').textContent=(current+1)+' / '+photos.length;}photos.forEach((p,i)=>p.addEventListener('click',()=>{show(i);dialog.showModal();document.body.classList.add('modal-open');}));dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));dialog.querySelector('.lightbox-nav button:first-child').addEventListener('click',()=>show(current-1));dialog.querySelector('.lightbox-nav button:last-child').addEventListener('click',()=>show(current+1));dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight')show(current+1);if(e.key==='ArrowLeft')show(current-1);});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});})();